class Solution {
public:
    string alphabetBoardPath(string target) {
        int pos[26][2];
        for (int i = 0; i < 26; i++) {
            pos[i][0] = i / 5;
            pos[i][1] = i % 5;
        }

        string result;
        int r = 0, c = 0;

        for (char ch : target) {
            int idx = ch - 'a';
            int tr = pos[idx][0], tc = pos[idx][1];
            int dr = tr - r, dc = tc - c;

            if (ch == 'z') {
                result += string(abs(dc), dc > 0 ? 'R' : 'L');
                result += string(abs(dr), dr > 0 ? 'D' : 'U');
            } else {
                result += string(abs(dr), dr > 0 ? 'D' : 'U');
                result += string(abs(dc), dc > 0 ? 'R' : 'L');
            }

            result += '!';
            r = tr;
            c = tc;
        }

        return result;
    }
};
